const solid=c=>[{type:"SOLID",color:c}];
async function T(chars,size,style,color,opts={}){const t=figma.createText();t.fontName={family:"Montserrat",style};t.fontSize=size;t.characters=chars;t.fills=solid(color);if(opts.name)t.name=opts.name;if(opts.lh)t.lineHeight={value:opts.lh,unit:"PIXELS"};if(opts.max){t.textAutoResize="HEIGHT";t.resize(opts.max,t.height);}if(opts.center)t.textAlignHorizontal="CENTER";return t;}
async function img(compId,w,h){const c=await figma.getNodeByIdAsync(compId);const i=c.createInstance();i.resize(w,h);try{if(i.fills&&i.fills[0]&&i.fills[0].type==="IMAGE"){const f=JSON.parse(JSON.stringify(i.fills));f[0].scaleMode="FILL";i.fills=f;}}catch(e){}return i;}
async function icon(compId,size,color){const c=await figma.getNodeByIdAsync(compId);const i=c.createInstance();i.resize(size,size);const walk=n=>{if(n.type==="VECTOR"||n.type==="BOOLEAN_OPERATION"){if(n.strokes&&n.strokes.length)n.strokes=solid(color);if(n.fills&&n.fills.length&&n.fills[0].type==="SOLID")n.fills=solid(color);}if("children"in n)n.children.forEach(walk);};walk(i);return i;}
function fr(name,w,h,opts={}){const f=figma.createFrame();f.name=name;f.resize(w,h);f.fills=opts.fill?solid(opts.fill):[];if(opts.radius!==undefined)f.cornerRadius=opts.radius;if(opts.clip)f.clipsContent=true;if(opts.layout){f.layoutMode=opts.dir||"VERTICAL";f.itemSpacing=opts.gap||0;f.paddingLeft=opts.pl||0;f.paddingRight=opts.pr||0;f.paddingTop=opts.pt||0;f.paddingBottom=opts.pb||0;f.primaryAxisAlignItems=opts.main||"MIN";f.counterAxisAlignItems=opts.cross||"MIN";f.primaryAxisSizingMode=opts.fixW===false?"AUTO":"FIXED";f.counterAxisSizingMode=opts.fixH===false?"AUTO":"FIXED";}return f;}
